sp_widget.client_script:
api.controller = function() {

    var c = this;

    c.submitComplaint = function() {

        if (c.submitting ||
            !c.data.use_case ||
            !c.data.mess_hall ||
            !c.data.meal_type ||
            !c.data.description) {

            c.data.message = "Please fill all required fields.";
            return;
        }

        c.submitting = true;
        c.data.action = "submit";
        c.server.update().then(function(response) {

            c.data.message = response.data.message;
            if (response.data.success) {
                c.data.use_case = "";
                c.data.mess_hall = "";
                c.data.meal_type = "";
                c.data.description = "";
            }
        }).finally(function() {
            c.submitting = false;
        });
    };

};

sp_widget.css:
.cfsa-complaint {
    max-width: 650px;
    margin: 20px auto;
    background: #ffffff;
    border-radius: 12px;
    box-shadow: 0 3px 12px rgba(0,0,0,0.15);
    overflow: hidden;
}

.complaint-header {
    background: #337ab7;
    color: white;
    padding: 22px;
    text-align: center;
}

.complaint-header h2 {
    margin: 0 0 8px;
    font-size: 24px;
}

.complaint-header p {
    margin: 0;
    font-size: 14px;
}

.complaint-body {
    padding: 25px;
}

.form-group {
    margin-bottom: 18px;
}

.form-group label {
    display: block;
    font-weight: bold;
    margin-bottom: 7px;
}

.form-control {
    width: 100%;
    border: 1px solid #cccccc;
    border-radius: 6px;
    padding: 10px;
}

textarea.form-control {
    resize: vertical;
}

.btn-primary {
    width: 100%;
    padding: 12px;
    border: none;
    border-radius: 6px;
    background: #337ab7;
    color: white;
    font-size: 16px;
    font-weight: bold;
}

.btn-primary:hover {
    background: #286090;
}

.alert {
    margin-top: 15px;
}

sp_widget.script:
(function() {

    data.mess_halls = [];
    var halls = new GlideRecord("x_snc_campus_foo_1_mess_hall");
    halls.addQuery("active", true);
    halls.orderBy("name");
    halls.query();
    while (halls.next()) {
        data.mess_halls.push({
            sys_id: halls.getUniqueValue(),
            name: halls.getDisplayValue("name")
        });
    }

    if (input && input.action == "submit") {

        var student = new GlideRecord("x_snc_campus_foo_1_student");
        student.addQuery("user", gs.getUserID());
        student.addQuery("active", true);
        student.setLimit(1);
        student.query();

        if (!student.next()) {
            data.message = "Your student profile could not be found.";
            data.success = false;
            return;
        }

        var gr = new GlideRecord("x_snc_campus_foo_1_food_complaint");

        gr.initialize();

        gr.student = student.getUniqueValue();
        gr.use_case = input.use_case;
        gr.mess_hall = input.mess_hall;
        gr.meal_type = input.meal_type;
        gr.description = input.description;

        var complaintId = gr.insert();

        data.success = !!complaintId;
        data.message = data.success ? "Complaint submitted successfully." : "The complaint could not be submitted.";

    }

})();
